    local aircraft = workspace:WaitForChild("PIayerAircraft"):WaitForChild(player.Name)
    local UpdateValue = ReplicatedStorage:WaitForChild("Remotes"):WaitForChild("UpdateValue")
    local remoteFolder = game:GetService("ReplicatedStorage").Remotes
    local paintRemote = nil

    for _, remote in pairs(remoteFolder:GetDescendants()) do
        if remote:IsA("RemoteFunction") and remote:FindFirstChild("paintRemote") then
            paintRemote = remote
            break
        end
    end

