    local function parseColor(str)
        local r, g, b = str:match("([^,]+),([^,]+),([^,]+)")
        return Color3.new(tonumber(r), tonumber(g), tonumber(b))
    end

    local function toGrid(studs)
        return math.clamp(studs / 2.5, 0.04, 1)
    end

    local function splitAxis(total)
        local pieces = {}
        local rem = total
        while rem > 0.001 do
            local chunk = math.min(2.5, rem)
            table.insert(pieces, chunk)
            rem = rem - chunk
        end
        if #pieces == 0 then pieces = {math.max(0.1, total)} end
        return pieces
    end

    local function calcOffsets(pieces, total)
        local offsets = {}
        local cursor = -total / 2
        for _, p in ipairs(pieces) do
            table.insert(offsets, cursor + p / 2)
            cursor = cursor + p
        end
        return offsets
    end

    local function expandBlocks(inputBlocks)
        local result = {}
        for _, block in ipairs(inputBlocks) do
            if type(block) ~= "table" or not block.Size or not block.Position then
                table.insert(result, block)
                continue
            end
            local size = parseVec3(block.Size)
            local pos  = parseVec3(block.Position)
            local rot  = block.Rotation and parseVec3(block.Rotation) or Vector3.zero
            local xPieces = splitAxis(size.X)
            local yPieces = splitAxis(size.Y)
            local zPieces = splitAxis(size.Z)
            if #xPieces == 1 and #yPieces == 1 and #zPieces == 1 then
                table.insert(result, block)
                continue
            end
            local xOff = calcOffsets(xPieces, size.X)
            local yOff = calcOffsets(yPieces, size.Y)
            local zOff = calcOffsets(zPieces, size.Z)
            local rotCF = CFrame.Angles(math.rad(rot.X), math.rad(rot.Y), math.rad(rot.Z))
            for ix, xSize in ipairs(xPieces) do
                for iy, ySize in ipairs(yPieces) do
                    for iz, zSize in ipairs(zPieces) do
                        local localOffset = Vector3.new(xOff[ix], yOff[iy], zOff[iz])
                        local worldOffset = rotCF:VectorToWorldSpace(localOffset)
                        local subPos = pos + worldOffset
                        local sub = {}
                        for k, v in pairs(block) do sub[k] = v end
                        sub.Size = string.format("%s,%s,%s", xSize, ySize, zSize)
                        sub.Position = string.format("%s,%s,%s", subPos.X, subPos.Y, subPos.Z)
                        table.insert(result, sub)
                    end
                end
            end
        end
        return result
    end

    local smallParts = {}
    for _, obj in ipairs(aircraft:GetDescendants()) do
        if obj.Name == "SmallPart" and obj:IsA("Model") then
            table.insert(smallParts, obj)
        end
    end

    table.sort(smallParts, function(a, b)
        return a:GetFullName() < b:GetFullName()
    end)

    local expandedBlocks = expandBlocks(blocks)

    print(string.format("SmallParts found: %d", #smallParts))
    print(string.format("Blocks in JSON: %d -> expanded to: %d sub-blocks", #blocks, #expandedBlocks))

    if #expandedBlocks > #smallParts then
        warn(string.format("Need %d parts but only %d available - %d sub-blocks will be skipped!",
            #expandedBlocks, #smallParts, #expandedBlocks - #smallParts))
    end

    local count = math.min(#expandedBlocks, #smallParts)
    print("Configuring", count, "parts...")

    for i = 1, count do
        local block = expandedBlocks[i]
        if type(block) ~= "table" or not block.Size then continue end
        local size = parseVec3(block.Size)
        local cfg = smallParts[i]:WaitForChild("Configuration")
        UpdateValue:FireServer(toGrid(size.X), cfg:WaitForChild("Size X"))
        UpdateValue:FireServer(toGrid(size.Y), cfg:WaitForChild("Size Y"))
        UpdateValue:FireServer(toGrid(size.Z), cfg:WaitForChild("Size Z"))
    end

    local typeCounts = {}
    for i = 1, count do
        local block = expandedBlocks[i]
        if type(block) ~= "table" then continue end
        local bt = block._blockType or "Unknown"
        typeCounts[bt] = (typeCounts[bt] or 0) + 1
    end

    for blockType, amount in pairs(typeCounts) do
        local defaultMatCode = MATERIAL_MAP[blockType] or "none"
        print(string.format("* found %d %s on original build (default mapped to %s)", amount, blockType, defaultMatCode))
    end

    local threads = {}
    for i = 1, count do
        local block = expandedBlocks[i]
        if type(block) ~= "table" then continue end
        local spart = smallParts[i]:FindFirstChild("SPart")
        local color = block.Color and parseColor(block.Color) or nil
        local matCode = getMatCode(block._blockType, block.Transparency)
        task.spawn(function()
            if color and spart then
                paintRemote:InvokeServer(spart, color)
            end
            if matCode then
                paintRemote:InvokeServer(smallParts[i], matCode)
            end
        end)
    end

    for _, t in ipairs(threads) do
        coroutine.resume(t)
    end

    print("Done! Configured", count, "SmallParts.")
end)

