"Rotation":"-103.0148,-90,0","Size":"0.136375,0.397375,0.16825","Color":"1,1,1","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2773},{"Position":"46.775775,22.58825,-26.287151","Rotation":"-180,0,135.0022","Size":"0.348125,0.877375,0.5","Color":"0.2745,0.2941,0.3098","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2774},{"Position":"45.3474,22.612125,-29.473276","Rotation":"-170.0016,0,180","Size":"0.1875,0.749375,0.590375","Color":"0.3216,0.3373,0.3569","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2775},{"Position":"46.75165,23.30675,-32.287651","Rotation":"90,0,90","Size":"1.85,1.875,0.5","Color":"0.2745,0.2941,0.3098","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2776},{"Position":"47.81615,22.07075,-29.478401","Rotation":"174.9981,0.0049,-179.9998","Size":"0.375,0.507125,0.40125","Color":"0.3216,0.3373,0.3569","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2777},{"Position":"42.14915,24.49975,-33.012526","Rotation":"-20.0007,-0.0006,14.9988","Size":"0.425,0.1625,0.0625","Color":"0.2549,0.2667,0.2863","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2778},{"Position":"42.2599,24.466125,-34.532901","Rotation":"85.0011,0.0048,174.9963","Size":"0.0625,0.30525,0.225","Color":"1,1,1","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2779},{"Position":"41.93415,24.119875,-32.443901","Rotation":"-38.8832,-41.6464,-77.2407","Size":"0.19625,0.069375,0.104875","Color":"0.2549,0.2667,0.2863","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2780},{"Position":"47.785025,22.065375,-29.539776","Rotation":"174.9981,0.0049,-179.9998","Size":"0.1875,0.507125,0.52625","Color":"0.3216,0.3373,0.3569","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2781},{"Position":"46.0419,22.599625,-26.704651","Rotation":"-179.9956,59.9958,-135.0069","Size":"0.35325,0.901625,0.5","Color":"0.2745,0.2941,0.3098","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2782},{"Position":"40.158025,24.80325,-28.387151","Rotation":"-170.0042,-0.0024,134.9986","Size":"0.0625,0.160625,0.16775","Color":"0.3216,0.3373,0.3569","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2783},{"Position":"40.404525,24.70125,-34.542901","Rotation":"85.008,60.005,-172.0029","Size":"0.082125,0.282125,0.08125","Color":"1,1,1","ss":true,"cc":true,"a":true,"tr":0,"Roughness":0.5,"Metalness":0.1,"_idx":2784}]}]===])


    local MOTOR_EDITOR_FRAME_FIX = CFrame.Angles(math.rad(180), 0, 0)


    local blocks = {}
    local motorBlocks = {}
    local regularBlocks = {}

    local source = (type(data) == "table" and data[2]) or (type(data) == "table" and data[1]) or data

    if type(source) == "table" then
        for blockType, blockList in pairs(source) do
            if type(blockList) == "table" then
                for _, block in ipairs(blockList) do
                    if type(block) == "table" then
                        block._blockType = blockType
                        table.insert(blocks, block)
                        if block._motorFlag then
                            table.insert(motorBlocks, block)
                        else
                            table.insert(regularBlocks, block)
                        end
                    end
                end
            end
        end
    end


    table.sort(regularBlocks, function(a, b)
        return (a._idx or 0) < (b._idx or 0)
    end)

    local function parseVec3(str)
        local x, y, z = str:match("([^,]+),([^,]+),([^,]+)")
        return Vector3.new(tonumber(x), tonumber(y), tonumber(z))
    end

    local function parseColor(str)
        local r, g, b = str:match("([^,]+),([^,]+),([^,]+)")
        return tonumber(r), tonumber(g), tonumber(b)
    end

    local function splitAxis(total)
        local pieces = {}
        local rem = total
        while rem > 0.001 do
            local chunk = math.min(2.5, rem)
            table.insert(pieces, chunk)
            rem = rem - chunk
        end
        if #pieces == 0 then pieces = {math.max(0.1, total)} end
        return pieces
    end

    local function calcOffsets(pieces, total)
        local offsets = {}
        local cursor = -total / 2
        for _, p in ipairs(pieces) do
            table.insert(offsets, cursor + p / 2)
            cursor = cursor + p
        end
        return offsets
    end

    local function expandBlocks(inputBlocks)
        local result = {}
        for _, block in ipairs(inputBlocks) do
            if type(block) ~= "table" or not block.Size or not block.Position then
                table.insert(result, block)
                continue
            end
            local pos  = parseVec3(block.Position)
            local rot  = block.Rotation and parseVec3(block.Rotation) or Vector3.zero
            local size = parseVec3(block.Size)
            local xPieces = splitAxis(size.X)
            local yPieces = splitAxis(size.Y)
            local zPieces = splitAxis(size.Z)
            if #xPieces == 1 and #yPieces == 1 and #zPieces == 1 then
                table.insert(result, block)
                continue
            end
            local xOff = calcOffsets(xPieces, size.X)
            local yOff = calcOffsets(yPieces, size.Y)
            local zOff = calcOffsets(zPieces, size.Z)
            local rotCF = CFrame.Angles(math.rad(rot.X), math.rad(rot.Y), math.rad(rot.Z))
            for ix, xSize in ipairs(xPieces) do
                for iy, ySize in ipairs(yPieces) do
                    for iz, zSize in ipairs(zPieces) do
                        local localOffset = Vector3.new(xOff[ix], yOff[iy], zOff[iz])
                        local worldOffset = rotCF:VectorToWorldSpace(localOffset)
                        local subPos = pos + worldOffset
                        local sub = {}
                        for k, v in pairs(block) do sub[k] = v end
                        sub.Size = string.format("%s,%s,%s", xSize, ySize, zSize)
                        sub.Position = string.format("%s,%s,%s", subPos.X, subPos.Y, subPos.Z)
                        table.insert(result, sub)
                    end
                end
            end
        end
        return result
    end

    local function findMotorInPlot(r, g, b)
        print(string.format("[MotorSearch] Looking for Color3.fromRGB(%d,%d,%d) ...", r, g, b))
        for _, obj in pairs(myplot:GetDescendants()) do
            if obj.Name == "Main" and (obj.Parent.Name == "MotorBlock" or obj.Parent.Name == "MotorBlock2") then
                local c = obj.Color
                if c == Color3.fromRGB(r, g, b) then
                    local otherPart = obj.Parent:FindFirstChild("Other")
                    if otherPart then
                        print(string.format("[MotorSearch] FOUND! fromRGB(%d,%d,%d) at %s", r, g, b, obj.Parent:GetFullName()))
                        return obj, otherPart
                    end
                elseif c.R == r/255 and c.G == g/255 and c.B == b/255 then
                    local otherPart = obj.Parent:FindFirstChild("Other")
                    if otherPart then
                        print(string.format("[MotorSearch] FOUND via new(%d,%d,%d) at %s", r, g, b, obj.Parent:GetFullName()))
                        return obj, otherPart
                    end
                end
            end
        end
        warn(string.format("[MotorSearch] NOT FOUND for fromRGB(%d,%d,%d)", r, g, b))
        return nil, nil
    end


    local motorMap = {}
    for _, b in ipairs(motorBlocks) do
        local gid = b._motorForGroup
        if gid then
            if not motorMap[gid] then
                local r, g, bl = parseColor(b.Color)
                if r then
                    local mainPart, otherPart = findMotorInPlot(r, g, bl)
                    if mainPart and otherPart then
                        motorMap[gid] = {
                            main = mainPart,
                            other = otherPart,
                            otherFromMain = mainPart.CFrame:ToObjectSpace(otherPart.CFrame)
                        }
                        print(string.format("[Motor] group %s -> fromRGB(%d,%d,%d)", tostring(gid), r, g, bl))
                    end
                end
            end
            if motorMap[gid] and b._motorFlag == "stationary" then
                motorMap[gid].motorPos = parseVec3(b.Position) or Vector3.zero
                motorMap[gid].motorRot = b.Rotation and parseVec3(b.Rotation) or Vector3.zero
            end
        end
    end


    local mainCentroid = Vector3.zero
    local mCount = 0
    local fixedModelOrigin = nil

    if type(data) == "table" and type(data._modelOrigin) == "string" then
        fixedModelOrigin = parseVec3(data._modelOrigin)
    end

    if fixedModelOrigin then
        mainCentroid = fixedModelOrigin
    else
        for _, b in ipairs(regularBlocks) do
            if b.Position then
                local p = parseVec3(b.Position)
                mainCentroid += p
                mCount += 1
            end
        end
        if mCount > 0 then mainCentroid = mainCentroid / mCount end
    end

    for gid, info in pairs(motorMap) do
        info.main.CanCollide = false
        info.other.CanCollide = false
        Unweld(info.other)
        local relPos = info.motorPos - mainCentroid
        local motorRot = info.motorRot or Vector3.zero
        local targetCF = CFrame.new(anchorBase.Position)
            * CFrame.new(relPos)
            * CFrame.Angles(math.rad(motorRot.X), math.rad(motorRot.Y), math.rad(motorRot.Z))
            * MOTOR_EDITOR_FRAME_FIX
        local weldOffset = anchorBase.CFrame:ToObjectSpace(targetCF)
        info.targetOtherCF = targetCF * info.otherFromMain
        Weld(anchorBase, info.main, weldOffset)
        print(string.format("[MotorWeld] group %s: pos (%.2f,%.2f,%.2f), rot (%.1f,%.1f,%.1f)",
            tostring(gid), relPos.X, relPos.Y, relPos.Z, motorRot.X, motorRot.Y, motorRot.Z))
    end

    local allExpanded = expandBlocks(regularBlocks)

    local allSmallParts = {}
    for _, obj in ipairs(aircraft:GetDescendants()) do
        if obj.Name == "SmallPart" and obj:IsA("Model") then
            local part = obj:FindFirstChild("SPart")
            if part then
                part.CanCollide = false
                table.insert(allSmallParts, part)
            end
        end
    end

    table.sort(allSmallParts, function(a, b)
        return a:GetFullName() < b:GetFullName()
    end)

    local needed = #allExpanded
    local count = math.min(needed, #allSmallParts)

    print(string.format("Blocks: %d regular + %d motor -> %d expanded, %d SParts available",
        #regularBlocks, #motorBlocks, needed, #allSmallParts))

    if needed > #allSmallParts then
        warn(string.format("Need %d parts but only %d available - %d will be skipped!",
            needed, #allSmallParts, needed - #allSmallParts))
    end

    -- Unweld needed SParts
    for i = 1, count do
        Unweld(allSmallParts[i])
    end

    print("Welding", count, "parts...")

    for i = 1, count do
        local block = allExpanded[i]
        if type(block) ~= "table" or not block.Position then continue end

        local gid = block._groupId or "main"
        local motorInfo = motorMap[gid]

        local currentAnchor = (motorInfo and motorInfo.other) or anchorBase

        local pos = parseVec3(block.Position)
        local rot = block.Rotation and parseVec3(block.Rotation) or Vector3.zero


        local modelRelativeCF = CFrame.new(pos - mainCentroid)
            * CFrame.Angles(math.rad(rot.X), math.rad(rot.Y), math.rad(rot.Z))
        local targetWorldCF = CFrame.new(anchorBase.Position) * modelRelativeCF
        local anchorCF = (motorInfo and motorInfo.targetOtherCF) or anchorBase.CFrame
        local offset = anchorCF:ToObjectSpace(targetWorldCF)

        Weld(currentAnchor, allSmallParts[i], offset)
    end

    print("Done! Welded", count, "parts. Motors found:", #motorBlocks > 0 and table.concat({}, ",") or "none")

end)
